    if(!csrfOk()){$melding='Sessie verlopen. Ververs de pagina.';$typeMelding='fout';}
    else{$slot=dataSlotOpen();try{$types=[];foreach((array)($_POST['types']??[]) as $rij){if(!is_array($rij))continue;$types[]=['id'=>$rij['id']??'','labels'=>['nl'=>$rij['label_nl']??'','en'=>$rij['label_en']??'','de'=>$rij['label_de']??''],'actief'=>!empty($rij['actief']),'leeftijd_min'=>$rij['leeftijd_min']??'','leeftijd_max'=>$rij['leeftijd_max']??'','jaarbedrag'=>$rij['jaarbedrag']??0,'inschrijfgeld'=>$rij['inschrijfgeld']??0,'pro_rata'=>!empty($rij['pro_rata'])];}if(lidmaatschapSchrijf($types)){schrijfLog($logBestand,$huidigeGebruiker,'lidmaatschapstypen_bijgewerkt',count($types).' type(s) aangeboden');$melding='Lidmaatschapstypen opgeslagen.';$typeMelding='ok';}else{$melding='Opslaan mislukt. Controleer of ieder type een unieke sleutel en Nederlandse naam heeft.';$typeMelding='fout';}}finally{dataSlotDicht($slot);}}
}
$types=lidmaatschapLees()['types'];$types[]=['id'=>'','labels'=>['nl'=>'','en'=>'','de'=>''],'actief'=>true,'leeftijd_min'=>null,'leeftijd_max'=>null,'jaarbedrag'=>0,'inschrijfgeld'=>0,'pro_rata'=>true];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lidmaatschapstypen</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1200px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:1fr repeat(3,1.3fr) .7fr .7fr .8fr .8fr;gap:10px}.veld label{display:block;font-weight:700;font-size:13px;margin-bottom:5px}.veld input{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px}.btn{border:0;background:#3a7a77;color:#fff;padding:10px 14px;border-radius:8px;font:inherit;font-weight:750}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}.meta{color:#68705f;font-size:13px}@media(max-width:1000px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Lidmaatschapstypen</h1><p class="meta">Dit is de enige tariefbron. Voeg bijvoorbeeld jeugd, senior, student, donateur of gezinslid toe. Leeftijdsgrenzen mogen leeg blijven. NL is verplicht; EN/DE vallen terug op NL als ze leeg zijn.</p><?php if($melding!==''):?><div class="melding <?=ltEsc($typeMelding)?>"><?=ltEsc($melding)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=ltEsc($csrfToken)?>"><?php foreach($types as $i=>$t):$labels=is_array($t['labels']??null)?$t['labels']:['nl'=>$t['label']??''];?><section class="card"><div class="grid"><div class="veld"><label>Sleutel</label><input name="types[<?=$i?>][id]" value="<?=ltEsc($t['id']??'')?>" placeholder="student"></div><div class="veld"><label>Naam NL</label><input name="types[<?=$i?>][label_nl]" value="<?=ltEsc($labels['nl']??'')?>" placeholder="Studentlid"></div><div class="veld"><label>Naam EN</label><input name="types[<?=$i?>][label_en]" value="<?=ltEsc($labels['en']??'')?>"></div><div class="veld"><label>Naam DE</label><input name="types[<?=$i?>][label_de]" value="<?=ltEsc($labels['de']??'')?>"></div><div class="veld"><label>Leeftijd vanaf</label><input type="number" min="0" max="120" name="types[<?=$i?>][leeftijd_min]" value="<?=ltEsc($t['leeftijd_min']??'')?>"></div><div class="veld"><label>Leeftijd t/m</label><input type="number" min="0" max="120" name="types[<?=$i?>][leeftijd_max]" value="<?=ltEsc($t['leeftijd_max']??'')?>"></div><div class="veld"><label>Jaarbedrag</label><input type="number" step="0.01" min="0" name="types[<?=$i?>][jaarbedrag]" value="<?=ltEsc($t['jaarbedrag']??0)?>"></div><div class="veld"><label>Inschrijfgeld</label><input type="number" step="0.01" min="0" name="types[<?=$i?>][inschrijfgeld]" value="<?=ltEsc($t['inschrijfgeld']??0)?>"></div></div><p><label><input type="checkbox" name="types[<?=$i?>][actief]" value="1" <?=!empty($t['actief'])?'checked':''?>> Actief</label> &nbsp; <label><input type="checkbox" name="types[<?=$i?>][pro_rata]" value="1" <?=!empty($t['pro_rata'])?'checked':''?>> Pro-rata bij instroom gedurende het jaar</label></p></section><?php endforeach;?><button class="btn" type="submit">Typen opslaan</button></form></main></body></html>
